function hasScrambledCopy(pattern: string, text: string): boolean {
  const m = pattern.length;
  const key = pattern.split("").sort().join("");
  for (let i = 0; i + m <= text.length; i++) {
    if (text.slice(i, i + m).split("").sort().join("") === key) return true;
  }
  return false;
}

