function hasScrambledCopy(pattern: string, text: string): boolean {
  const m = pattern.length;
  if (m > text.length) return false;
  const want = new Array(26).fill(0), have = new Array(26).fill(0);
  for (let i = 0; i < m; i++) {
    want[pattern.charCodeAt(i) - 97]++;
    have[text.charCodeAt(i) - 97]++;
  }
  const same = () => want.every((v, i) => v === have[i]);
  if (same()) return true;
  for (let end = m; end < text.length; end++) {
    have[text.charCodeAt(end) - 97]++;
    have[text.charCodeAt(end - m) - 97]--;
    if (same()) return true;
  }
  return false;
}

