function hasScrambledCopy(pattern: string, text: string): boolean {
  const m = pattern.length;
  if (m > text.length) return false;
  const diff = new Array(26).fill(0); // window count minus pattern count
  for (let i = 0; i < m; i++) {
    diff[pattern.charCodeAt(i) - 97]--;
    diff[text.charCodeAt(i) - 97]++;
  }
  let off = diff.filter(d => d !== 0).length; // letters whose counts disagree
  if (off === 0) return true;
  const bump = (c: number, delta: number) => {
    if (diff[c] === 0) off++;
    diff[c] += delta;
    if (diff[c] === 0) off--;
  };
  for (let end = m; end < text.length; end++) {
    bump(text.charCodeAt(end) - 97, 1);
    bump(text.charCodeAt(end - m) - 97, -1);
    if (off === 0) return true;
  }
  return false;
}

