class Solution:
    def hasScrambledCopy(self, pattern: str, text: str) -> bool:
        m = len(pattern)
        if m > len(text):
            return False
        diff = [0] * 26  # window count minus pattern count
        for i in range(m):
            diff[ord(pattern[i]) - 97] -= 1
            diff[ord(text[i]) - 97] += 1
        off = sum(1 for d in diff if d != 0)

        def bump(c: int, delta: int) -> None:
            nonlocal off
            if diff[c] == 0:
                off += 1
            diff[c] += delta
            if diff[c] == 0:
                off -= 1

        if off == 0:
            return True
        for end in range(m, len(text)):
            bump(ord(text[end]) - 97, 1)
            bump(ord(text[end - m]) - 97, -1)
            if off == 0:
                return True
        return False

